eyes=[
 dict(id="pan310",short="Panegyrist 310",name="Anonymous orator of Panegyrici Latini VI(7)",life="fl. 310",
  role="A Gallic professional orator, probably from Autun, speaking before Constantine at the imperial court",
  side="Constantine's court in Gaul",where="Trier, the imperial residence on the Moselle",lat=49.756,lon=6.641,
  waypoints=[{"lat":43.296,"lon":5.37,"label":"Massilia: Maximian's revolt ends, 310"},{"lat":48.384,"lon":5.483,"label":"the temple of Apollo (often identified as Grand, Vosges)"},{"lat":49.756,"lon":6.641,"label":"Trier: speech delivered, c. 310"}],
  vantage=1,vantage_label="court orator, speaking within weeks of the reported vision",form="panegyric (speech delivered aloud, later collected)",language="Latin",
  authenticity="Survives in the Panegyrici Latini collection, known from a single manuscript found at Mainz in 1433 and copied in Italy. Conventionally dated to the summer of 310 and delivered at Trier during the city's anniversary celebrations. The orator's name is lost. The passage on Apollo (ch. 21) is the only contemporary report of a vision seen by Constantine before 312.",
  bio="The orator speaks only months after Maximian, Constantine's father-in-law, revolted and died at Massilia. He gives Constantine a new ancestor, the emperor Claudius II, and a new divine patron, Apollo, instead of the Tetrarchic Hercules. His Constantine sees Apollo, with Victory, offering laurel wreaths marked with the numeral thirty: a pagan vision that has nothing Christian in it.",
  sources=[{"title":"C. Ware, A Literary Commentary on Panegyrici Latini VI(7) (Cambridge, 2021), excerpt","url":WARE},{"title":"C. E. V. Nixon and B. S. Rodgers, In Praise of Later Roman Emperors: The Panegyrici Latini (Berkeley, 1994)","url":""}]),
 dict(id="constantine",short="Constantine",name="Flavius Valerius Constantinus (Constantine I)",life="c. 272/273–337",
  role="Son of the emperor Constantius I; acclaimed emperor at York in 306, aged about 33; sole ruler of the empire from 324",
  side="His own army in Gaul and Britain; later the whole Roman empire",where="Gaul and the Rhine (306–312), Rome (October 312), then Milan, the Balkans, Nicomedia and Constantinople",lat=41.935,lon=12.467,
  waypoints=[{"lat":53.96,"lon":-1.08,"label":"York: acclaimed, July 306"},{"lat":49.756,"lon":6.641,"label":"Trier, 306–312"},{"lat":41.935,"lon":12.467,"label":"Milvian Bridge, 28 Oct 312"},{"lat":45.464,"lon":9.19,"label":"Milan, early 313"},{"lat":41.008,"lon":28.98,"label":"Constantinople, dedicated 330"},{"lat":40.77,"lon":29.5,"label":"near Nicomedia, died 337"}],
  vantage=0,vantage_label="the man who said he saw the sign",form="laws, letters and edicts; his vision known only through others",language="Latin (some letters issued in Greek)",
  authenticity="No account of the vision in Constantine's own hand survives. His version is known through Eusebius, who says Constantine told it to him under oath many years later. Constantine's own words survive in laws preserved in the Theodosian and Justinian Codes and in letters quoted by Eusebius, Lactantius and Optatus; some of the letters in the Life of Constantine have been questioned, though most scholars now accept them.",
  bio="Constantine owed his throne to his father's army, not to the Tetrarchic system, and had to explain his power to soldiers, senators and provincials who worshipped different gods. Between 310 and 312 the divine companion named in his court speeches moves from Apollo and the Sun to an unnamed supreme deity and then, in Christian writers, to the God of the Christians. He kept the pagan title of chief priest (pontifex maximus) and was baptised only on his deathbed.",
  sources=[{"title":"Eusebius, Life of Constantine I.28 (NPNF 2nd ser. vol. 1, trans. E. C. Richardson, 1890)","url":VC28},{"title":"Lactantius, On the Deaths of the Persecutors 48 (letter of 313)","url":LACT48}]),
 dict(id="maxentius",short="Maxentius",name="Marcus Aurelius Valerius Maxentius",life="c. 278–312",
  role="Son of the retired emperor Maximian; proclaimed emperor in Rome on 28 October 306; ruled Italy and, for a time, Africa",
  side="Rome and Italy; the Praetorian Guard and Roman people who raised him",where="Rome, inside the Aurelian walls",lat=41.902,lon=12.496,
  vantage=0,vantage_label="the loser, known only through his enemies and his coins",form="coins and buildings; his acts reported by hostile writers",language="Latin",
  authenticity="Nothing Maxentius wrote survives. His side of 312 is reconstructed from his coinage (which styles him 'conservator' of his city), his buildings in Rome, and the accounts of Lactantius, the panegyrists, Eusebius and Zosimus, all written after his defeat and most of them hostile.",
  bio="Maxentius was the emperor of the city of Rome itself, restoring its monuments and courting its people. Christian writers call him a tyrant and a sorcerer, yet he had ended persecution in his territory and returned church property in Rome. His reliance on the Sibylline books before the battle, reported by both a Christian and a pagan writer, makes him the other half of the story of divine signs in October 312.",
  sources=[{"title":"Lactantius, On the Deaths of the Persecutors 44 (ANF vol. 7, trans. W. Fletcher, 1886)","url":LACT_URL},{"title":"Zosimus, New History 2.16 (anonymous English translation, London, 1814)","url":ZOS16}]),
 dict(id="pan313",short="Panegyrist 313",name="Anonymous orator of Panegyrici Latini XII(9)",life="fl. 313",
  role="A Gallic orator, perhaps a veteran of earlier court speeches; sometimes, probably wrongly, identified with Nazarius",
  side="Constantine's court in Gaul",where="Trier",lat=49.756,lon=6.641,
  vantage=2,vantage_label="court orator a year after the battle",form="panegyric (speech delivered aloud, later collected)",language="Latin",
  authenticity="Preserved in the Panegyrici Latini collection. Delivered at Trier in 313, after Constantine's return from Italy. The orator was not at the battle and relies on court reports. Differences of style and a more cautiously monotheistic tone have been used to argue it is not by Nazarius.",
  bio="The first surviving account of the campaign of 312 by a non-Christian speaker. He says Constantine marched on Rome against the warnings of the soothsayers and human advice, prompted by a divine power, and ends with a prayer to a supreme creator of many names. He mentions no sign in the sky and no mark on shields.",
  sources=[{"title":"Nixon and Rodgers, In Praise of Later Roman Emperors (1994), Pan. Lat. XII(9)","url":""},{"title":"Panegyrici Latini (overview)","url":"https://wikipedia.com/wiki/Latin_Panegyric"}]),
 dict(id="lactantius",short="Lactantius",name="Lucius Caecilius Firmianus Lactantius",life="c. 250–c. 325",
  role="North African rhetorician, once a teacher of Latin rhetoric at Diocletian's court in Nicomedia; a Christian convert; in old age tutor to Constantine's son Crispus in Gaul",
  side="Christian; close to Constantine's court",where="Nicomedia and later Gaul (where he wrote is debated)",lat=40.765,lon=29.94,
  waypoints=[{"lat":40.765,"lon":29.94,"label":"Nicomedia, during the persecution"},{"lat":49.756,"lon":6.641,"label":"Trier, tutor to Crispus (date debated)"}],
  vantage=2,vantage_label="Christian writer within about three years of the battle",form="pamphlet history (De mortibus persecutorum)",language="Latin",
  authenticity="De mortibus persecutorum survives in a single manuscript (Paris, BnF lat. 2627, from Moissac), first printed in 1679. Its attribution to Lactantius is now generally accepted. Written c. 314–315. It preserves the Latin text of the letter of Licinius of 13 June 313 and Galerius's edict of 311.",
  bio="Lactantius had lived through the Great Persecution in Nicomedia and wrote to show that every persecuting emperor died badly. His is the earliest surviving account linking Constantine's victory to the Christian God: a dream on the eve of battle commanding a heavenly sign on the shields. He tells a matching story of Licinius receiving a prayer from an angel in 313.",
  sources=[{"title":"Of the Manner in Which the Persecutors Died, ch. 44 (ANF vol. 7, trans. W. Fletcher, 1886), BKV Fribourg","url":LACT_URL},{"title":"Ch. 46, CCEL","url":LACT46},{"title":"Ch. 48, BKV Fribourg (Latin and English)","url":LACT48}]),
 dict(id="licinius",short="Licinius",name="Valerius Licinianus Licinius",life="c. 265–325",
  role="Galerius's old comrade, made Augustus in 308; Constantine's ally and brother-in-law from 313, later his rival",
  side="The eastern half of the empire (Balkans, then Asia Minor and the East)",where="Milan (Feb 313), Thrace (April 313), Nicomedia (June 313)",lat=40.765,lon=29.94,
  waypoints=[{"lat":45.464,"lon":9.19,"label":"Milan, meeting with Constantine, early 313"},{"lat":41.677,"lon":26.556,"label":"near Adrianople, battle with Daia, 313"},{"lat":40.765,"lon":29.94,"label":"Nicomedia, letter posted 13 June 313"},{"lat":41.025,"lon":29.03,"label":"Chrysopolis, defeated 324"},{"lat":40.64,"lon":22.94,"label":"Thessalonica, put to death 325"}],
  vantage=0,vantage_label="co-emperor; issuer of the 'Edict of Milan'",form="imperial letter (rescript) and others' reports",language="Latin (Greek version in Eusebius)",
  authenticity="The so-called Edict of Milan is a letter Licinius issued to provincial governors in the East after he and Constantine met at Milan. It survives in Latin in Lactantius (ch. 48) and in Greek in Eusebius, Church History X.5. It was not an edict issued at Milan. Licinius's dream is reported only by Lactantius.",
  bio="Licinius is the other emperor of 313, and his story mirrors Constantine's: Lactantius says an angel gave him a prayer to a supreme God before his battle with Maximinus Daia. He is the one who posted the toleration letter in Nicomedia, the city where persecution had begun ten years before. Christian writers who praised him in 313 later treated him as a persecutor after Constantine destroyed him.",
  sources=[{"title":"Lactantius, ch. 46 (Licinius's dream), CCEL","url":LACT46},{"title":"Lactantius, ch. 48 (the letter), BKV Fribourg","url":LACT48}]),
 dict(id="senate",short="Senate of Rome",name="The Senate and People of Rome (SPQR)",life="institution",
  role="The Roman Senate, which voted honours to the victor and dedicated the arch beside the Colosseum",
  side="The traditional, largely pagan aristocracy of Rome",where="Rome, between the Palatine and the Colosseum",lat=41.8898,lon=12.4906,
  vantage=1,vantage_label="the city that received the victor, speaking in stone",form="inscription (official record)",language="Latin",
  authenticity="The dedicatory inscription survives on both faces of the attic of the Arch of Constantine (CIL VI 1139). The arch reuses sculpture from monuments of Trajan, Hadrian and Marcus Aurelius and adds a Constantinian frieze showing the campaign and the battle at the bridge.",
  bio="The senators had to praise a conqueror who had just killed their emperor. Their inscription says Constantine acted 'instinctu divinitatis' (by the prompting of the divinity) and by greatness of mind. It names no god. Christians and pagans could each read their own deity into the phrase, which may have been the point.",
  sources=[{"title":"World History Encyclopedia, 'The Arch of Constantine, Rome' (inscription text)","url":ARCH},{"title":"The Arch of Constantine, Judaism and Rome database","url":"https://heurist.huma-num.fr/heurist/judaism_and_rome/view/90"}]),
 dict(id="ticinum",short="Ticinum mint",name="The imperial mint at Ticinum (Pavia)",life="mint active 274–327",
  role="One of the imperial mints of northern Italy, striking coins and presentation medallions in Constantine's name",
  side="Constantine's administration",where="Ticinum (modern Pavia), northern Italy",lat=45.185,lon=9.155,
  vantage=1,vantage_label="official images, struck under the emperor's authority",form="coins and medallions (dated by type)",language="Latin legends; images",
  authenticity="The silver medallion of Ticinum showing Constantine in a crested helmet bearing a small chi-rho badge is generally dated c. 315 (the decennalia). Only a few specimens survive; the best known is in the Staatliche Münzsammlung, Munich. Dates of coin types rest on numismatic catalogues (RIC VI–VII), not on dated documents.",
  bio="Coins were the government's most widely seen statements. The Ticinum medallion carries what is often called the earliest chi-rho on an official image of Constantine, yet the same mints went on striking coins to the Unconquered Sun as his companion for years. Together they show a public image that did not choose between the two.",
  sources=[{"title":"Silver medallion of Constantine I (bavarikon, Staatliche Münzsammlung München)","url":MED},{"title":"Ticinum nummus with labarum, 319–320 (Judaism and Rome database)","url":COIN382}]),
 dict(id="eusebius",short="Eusebius",name="Eusebius of Caesarea (Eusebius Pamphili)",life="c. 260/265–339",
  role="Bishop of Caesarea in Palestine from c. 313; scholar, historian and apologist; attended the Council of Nicaea in 325",
  side="Christian; an eastern bishop who met Constantine only after 324",where="Caesarea Maritima in Palestine; Nicaea (325); Constantinople (335–336)",lat=32.5,lon=34.892,
  waypoints=[{"lat":32.5,"lon":34.892,"label":"Caesarea, writing the Church History"},{"lat":40.43,"lon":29.72,"label":"Nicaea, council of 325"},{"lat":41.008,"lon":28.98,"label":"Constantinople, tricennalia, 336"}],
  vantage=3,vantage_label="distant historian in 312; the emperor's confidant later",form="church history and biography (written later)",language="Greek",
  authenticity="The Church History went through several editions; book IX, with the battle at the Milvian Bridge, belongs to an edition usually dated c. 313–316 (some argue later, up to c. 325). The Life of Constantine was written after the emperor's death in May 337 and left unfinished at Eusebius's death in 339. Its account of the vision is the only one said to come from Constantine himself.",
  bio="Eusebius gives two accounts of 312, and they differ. In the Church History the victory is God's answer to prayer and Maxentius drowns like Pharaoh, but there is no vision. A quarter of a century later, in the Life, a cross of light appears in the noon sky with the words 'Conquer by this', seen by the whole army, followed by a dream of Christ; Eusebius says Constantine swore to it when telling him long afterwards.",
  sources=[{"title":"Life of Constantine I.28 (NPNF 2nd ser. vol. 1, trans. E. C. Richardson, 1890), CCEL","url":VC28},{"title":"Fordham Internet Medieval Sourcebook: Eusebius on the conversion of Constantine","url":FORD},{"title":"Life of Constantine record, Judaism and Rome database","url":HEUR_VC}]),
 dict(id="nazarius",short="Nazarius",name="Nazarius",life="fl. 321",
  role="Celebrated rhetorician of Bordeaux; his daughter was also known as a speaker",
  side="Constantine's court and the Gallic schools",where="Rome (speech given in the emperor's absence)",lat=41.902,lon=12.496,
  vantage=3,vantage_label="orator nine years after the battle",form="panegyric (speech delivered aloud, later collected)",language="Latin",
  authenticity="Panegyrici Latini IV(10), delivered in 321 for the fifteenth year of Constantine's reign and the fifth of his sons Crispus and Constantine as Caesars. The place (Rome) and month (probably March) rest on the speech's content and modern commentary.",
  bio="Nazarius adds a new marvel: armies sent from heaven, said to be talked about across Gaul, led by Constantine's deified father Constantius, came to help in 312. Like the earlier orators he names no Christian sign, which shows that in 321 the official miracle of the campaign could still be told in a non-Christian way.",
  sources=[{"title":"Nazarius (rhetorician)","url":NAZ},{"title":"Nixon and Rodgers, In Praise of Later Roman Emperors (1994), Pan. Lat. IV(10)","url":""}]),
 dict(id="zosimus",short="Zosimus",name="Zosimus",life="fl. c. 490–510",
  role="Retired treasury official (advocatus fisci) in Constantinople; a pagan historian",
  side="Pagan, hostile to Constantine",where="Constantinople, writing nearly two centuries later",lat=41.008,lon=28.98,
  vantage=4,vantage_label="hostile pagan historian, nearly 200 years later",form="history (written long after)",language="Greek",
  authenticity="The New History survives in a single Vatican manuscript (Vat. gr. 156). Zosimus wrote c. 498–518, drawing on the lost pagan history of Eunapius (c. 400). The English translation quoted here was printed in London in 1814 (W. Green and T. Chaplin), probably by J. Davis.",
  bio="Zosimus blamed Constantine and Christianity for Rome's decline. His account of 312 contains no Christian sign at all; instead Maxentius reads the Sibylline oracle as favouring himself and a flock of owls settles on the wall. He also tells a hostile story of why Constantine turned Christian, which Christian writers rejected.",
  sources=[{"title":"Zosimus, New History 2.16 (1814 translation), Livius.org","url":ZOS16},{"title":"Zosimus, New History book 2, Livius.org","url":ZOS2}]),
]
